INSERT INTO rdm.standard_release (family, release_code, title, source_uri) VALUES
  ('BSP', 'D23B', 'Buy-Ship-Pay Reference Data Model — bibliothèque et structures d''échange', 'https://github.com/uncefact/spec-JSONschema/tree/main/JSONschema2020-12/library/BuyShipPay/D23B');
INSERT INTO rdm.bsp_domain (code, label_fr, label_en, description, sort_order) VALUES
  ('COMMERCIAL', 'Commercial', 'Commercial', 'Relation acheteur–vendeur : demande de prix, contrat de vente, commande, confirmation et livraison des marchandises ou services.', 10),
  ('TRANSPORT', 'Transport et logistique', 'Transport and logistics', 'Contrat de service de transport, réservation, enlèvement, manutention, entreposage, acheminement multimodal et livraison.', 20),
  ('REGULATORY', 'Réglementaire', 'Regulatory', 'Formalités des autorités : licences et certificats, déclarations en douane export, transit et import, contrôles des autres agences (phytosanitaire, santé, environnement, normes, ports).', 30),
  ('FINANCIAL', 'Financier', 'Financial', 'Facturation, moyens et garanties de paiement (crédit documentaire), assurance, règlement et paiement des droits et taxes.', 40);
INSERT INTO rdm.bsp_process (code, phase, domain, label_fr, label_en, description, documents, sort_order) VALUES
  ('IDENTIFY_PARTNER', 'BUY', 'COMMERCIAL', 'Identifier le partenaire commercial', 'Identify potential trading partner', 'Recherche de fournisseurs ou de clients, demande de prix et de catalogue, sélection du partenaire.', '{"Demande de prix","Offre / devis","Catalogue"}', 10),
  ('ESTABLISH_AGREEMENT', 'BUY', 'COMMERCIAL', 'Conclure l''accord commercial', 'Establish business agreement', 'Négociation et conclusion du contrat de vente : prix, Incoterm (Rec. 5), conditions de paiement (Rec. 17), délais.', '{"Contrat de vente","Facture pro forma"}', 20),
  ('ORDER', 'BUY', 'COMMERCIAL', 'Commander', 'Order', 'Émission de la commande client par l''acheteur, modification et réponse du vendeur.', '{"Commande","Modification de commande","Réponse à commande"}', 30),
  ('PREPARE_EXPORT', 'SHIP', 'REGULATORY', 'Préparer l''exportation', 'Prepare for export', 'Obtention des licences, certificats d''origine, phytosanitaires (NIMP 12), sanitaires ou de conformité exigés à l''export ou à l''import.', '{"Licence d''exportation","Certificat d''origine","Certificat phytosanitaire","Certificat d''inspection"}', 40),
  ('ARRANGE_TRANSPORT', 'SHIP', 'TRANSPORT', 'Organiser le transport', 'Arrange transport', 'Contrat de service de transport entre l''acheteur de services de transport et le prestataire : réservation, instructions d''expédition (Rec. 22).', '{"Réservation","Instructions d''expédition","Liste de colisage"}', 50),
  ('EXPORT', 'SHIP', 'REGULATORY', 'Exporter', 'Export', 'Déclaration en douane d''exportation, contrôles et mainlevée au bureau de sortie.', '{"Déclaration d''exportation","Bon à enlever export"}', 60),
  ('TRANSPORT', 'SHIP', 'TRANSPORT', 'Transporter', 'Transport', 'Prise en charge, chargement, acheminement (éventuels transbordements, transit), suivi de statut et déchargement.', '{"Connaissement","Lettre de transport aérien","Lettre de voiture CMR / e-CMR","Manifeste","Rapport de statut"}', 70),
  ('PREPARE_IMPORT', 'SHIP', 'REGULATORY', 'Préparer l''importation', 'Prepare for import', 'Licences et autorisations d''importation, notifications préalables (formulaires FAL, informations préalables sur la cargaison).', '{"Licence d''importation","Déclaration sommaire d''entrée","Formulaires FAL"}', 80),
  ('IMPORT', 'SHIP', 'REGULATORY', 'Importer', 'Import', 'Déclaration en douane d''importation, contrôles des autorités, paiement des droits et taxes, mainlevée.', '{"Déclaration d''importation","Quittance","Bon à enlever"}', 90),
  ('DELIVER', 'SHIP', 'TRANSPORT', 'Livrer et réceptionner', 'Deliver and receive', 'Livraison au destinataire final, preuve de livraison, avis de réception.', '{"Bon de livraison","Avis de réception"}', 100),
  ('INVOICE', 'PAY', 'FINANCIAL', 'Facturer', 'Invoice / claim payment', 'Émission de la facture commerciale (Rec. 6) et des factures de fret et de services.', '{"Facture commerciale","Facture de fret"}', 110),
  ('PAY', 'PAY', 'FINANCIAL', 'Payer', 'Pay', 'Ordre de paiement, crédit documentaire, avis de règlement et paiements des droits et taxes.', '{"Ordre de paiement","Crédit documentaire","Avis de règlement"}', 120);
INSERT INTO rdm.bsp_entity (code, label_fr, label_en, definition, abie_code, bie_path, key_paths, note, sort_order) VALUES
  ('SALES_ORDER', 'Commande client', 'Sales Order', 'Document contractuel par lequel un acheteur initie une transaction avec un vendeur pour la fourniture de biens ou de services, selon des conditions énoncées dans un devis ou connues de l''acheteur ; il porte aussi les informations de transport et réglementaires requises par les intermédiaires et autorités.', 'supplyChainTradeTransaction', 'tradeTransaction', '{"tradeTransaction/applicableHeaderTradeAgreement/buyerOrderReferencedDocument/issuerAssignedId"}', NULL, 10),
  ('TRADE_ITEM', 'Article commercial', 'Trade Item', 'Niveau le plus bas des informations commerciales d''une commande : marchandise ou service, avec code produit, quantité, prix unitaire et, pour les échanges transfrontaliers, position tarifaire douanière.', 'tradeLineItem', 'tradeTransaction/includedTradeLineItem', '{"tradeTransaction/includedTradeLineItem/specifiedTradeProduct/id","tradeTransaction/includedTradeLineItem/specifiedLineTradeDelivery/billedQuantity"}', NULL, 20),
  ('SHIPMENT', 'Expédition / livraison', 'Shipment / Delivery', 'Ensemble identifiable d''un ou plusieurs articles commerciaux transportés ensemble du vendeur (expéditeur d''origine) à l''acheteur (destinataire final).', 'headerTradeDelivery', 'tradeTransaction/applicableHeaderTradeDelivery', '{"tradeTransaction/shipmentId"}', 'La Référence Unique d''Expédition (UCR, Rec. OMD) est portée par Supply Chain_ Trade Transaction. Shipment. Identifier.', 30),
  ('CONSIGNMENT', 'Envoi (ordre de service de transport)', 'Consignment (Transport Service Order)', 'Ensemble identifiable séparément d''articles en consignation transporté d''un expéditeur à un destinataire par un ou plusieurs modes de transport, tel que spécifié dans un seul contrat de service de transport.', 'consignment', 'specifiedConsignment', '{"specifiedConsignment/id","specifiedConsignment/customsId","specifiedConsignment/carrierAssignedId"}', NULL, 40),
  ('CONSIGNMENT_ITEM', 'Article en consignation', 'Consignment Item', 'Quantité identifiable séparément de produits regroupés par code tarifaire douanier ou par emballage pour le transport ; niveau le plus bas d''information d''un envoi.', 'consignmentItem', 'specifiedConsignment/includedConsignmentItem', '{"specifiedConsignment/includedConsignmentItem/includedTradeLineItem/specifiedTradeProduct/designatedProductClassification/classCode"}', NULL, 50),
  ('CUSTOMS_DECLARATION', 'Déclaration en douane (import, export, transit)', 'Import/Export/Transit Customs Declaration', 'Document par lequel les envois sont déclarés pour le dédouanement, conformément à la formule-cadre ; une position tarifaire (Système harmonisé de l''OMD) est fournie pour chaque article en consignation.', 'crossBorderRegulatoryProcedure', 'specifiedConsignment/applicableCrossBorderRegulatoryProcedure', '{"specifiedConsignment/customsId","specifiedConsignment/applicableCrossBorderRegulatoryProcedure/typeCode"}', 'Le BSP Master porte la déclaration (exchangedDeclaration) ; le SCRDM l''exclut et la représente par la procédure réglementaire transfrontalière de l''envoi. Le MD de l''OMD en donne la forme complète.', 60),
  ('CUSTOMS_ITEM', 'Article douanier', 'Customs Item', 'Article en consignation, article commercial ou agrégation de ceux-ci ayant une même position tarifaire douanière, déclaré séparément à la douane.', 'consignmentItem', 'specifiedConsignment/includedConsignmentItem', '{"specifiedConsignment/includedConsignmentItem/tariffQuantity","specifiedConsignment/includedConsignmentItem/declaredValueForCustomsAmount"}', NULL, 70),
  ('TRANSPORT_MOVEMENT', 'Mouvement de transport', 'Transport Movement', 'Déplacement des marchandises par un moyen de transport sur une étape (pré-acheminement, transport principal, post-acheminement).', 'logisticsTransportMovement', 'specifiedConsignment/mainCarriageLogisticsTransportMovement', '{"specifiedConsignment/mainCarriageLogisticsTransportMovement/modeCode","specifiedConsignment/mainCarriageLogisticsTransportMovement/id"}', NULL, 80),
  ('TRANSPORT_MEANS', 'Moyen de transport', 'Transport Means', 'Dispositif utilisé pour transporter des marchandises d''un endroit à un autre (navire, aéronef, véhicule, train).', 'logisticsTransportMeans', 'specifiedConsignment/mainCarriageLogisticsTransportMovement/usedLogisticsTransportMeans', '{"specifiedConsignment/mainCarriageLogisticsTransportMovement/usedLogisticsTransportMeans/typeCode","specifiedConsignment/mainCarriageLogisticsTransportMovement/usedLogisticsTransportMeans/name"}', NULL, 90),
  ('TRANSPORT_EQUIPMENT', 'Équipement de transport', 'Transport Equipment', 'Équipement utilisé pour contenir, protéger ou sécuriser une cargaison à des fins logistiques (conteneur, remorque, unité de charge).', 'logisticsTransportEquipment', 'specifiedConsignment/utilizedLogisticsTransportEquipment', '{"specifiedConsignment/utilizedLogisticsTransportEquipment/id","specifiedConsignment/utilizedLogisticsTransportEquipment/affixedLogisticsSeal/id"}', NULL, 100),
  ('TRANSPORT_PACKAGE', 'Colis de transport', 'Transport Package', 'Emballage ou contenant autonome dans lequel des marchandises sont contenues pour le transport (caisse, baril…), rempli, partiellement rempli ou vide.', 'logisticsPackage', 'specifiedConsignment/transportLogisticsPackage', '{"specifiedConsignment/transportLogisticsPackage/typeCode","specifiedConsignment/transportLogisticsPackage/itemQuantity"}', 'Pour les exigences douanières, un colis de transport peut définir deux niveaux supplémentaires de sous-emballage.', 110);
INSERT INTO rdm.bsp_entity_relation (from_entity, to_entity, cardinality, rule_fr) VALUES
  ('SALES_ORDER', 'TRADE_ITEM', '1..n', 'Une commande client est composée d''un ou plusieurs articles commerciaux.'),
  ('TRADE_ITEM', 'SHIPMENT', '1..1', 'Un article commercial est lié à une expédition.'),
  ('SHIPMENT', 'TRADE_ITEM', '1..n', 'Une expédition est composée de tout ou partie des articles commerciaux d''une ou plusieurs commandes.'),
  ('SHIPMENT', 'CONSIGNMENT', '1..n', 'Une expédition peut constituer une partie ou la totalité d''un envoi, ou être transportée dans différents envois.'),
  ('CONSIGNMENT', 'SHIPMENT', '1..n', 'Un envoi peut faire référence à une ou plusieurs expéditions.'),
  ('CONSIGNMENT', 'CONSIGNMENT_ITEM', '1..n', 'Un envoi est composé d''un ou plusieurs articles en consignation.'),
  ('CONSIGNMENT', 'CUSTOMS_ITEM', '1..n', 'Un envoi est composé d''un ou plusieurs articles douaniers à déclarer à la douane.'),
  ('CONSIGNMENT', 'TRANSPORT_EQUIPMENT', '0..n', 'Un envoi peut regrouper un ou plusieurs équipements de transport.'),
  ('CONSIGNMENT', 'TRANSPORT_PACKAGE', '0..n', 'Un envoi agrège des colis de transport.'),
  ('CONSIGNMENT_ITEM', 'TRADE_ITEM', '1..n', 'Un article en consignation peut contenir un ou plusieurs articles commerciaux (agrégés par position tarifaire ou emballage).'),
  ('CONSIGNMENT_ITEM', 'TRANSPORT_EQUIPMENT', '0..1', 'Un article en consignation peut être contenu dans un équipement de transport.'),
  ('CUSTOMS_DECLARATION', 'CUSTOMS_ITEM', '1..n', 'Une déclaration d''exportation, d''importation ou de transit contient un ou plusieurs articles douaniers.'),
  ('CUSTOMS_DECLARATION', 'CONSIGNMENT', '1..1', 'Une déclaration ne peut avoir qu''un seul UCR douanier ; un envoi peut avoir un ou plusieurs UCR douaniers.'),
  ('CUSTOMS_ITEM', 'TRADE_ITEM', '1..n', 'Un article douanier peut faire référence à un ou plusieurs articles commerciaux ; il n''a qu''une seule position tarifaire.'),
  ('TRANSPORT_MOVEMENT', 'TRANSPORT_MEANS', '1..1', 'Un moyen de transport correspond à un mouvement de transport et fonde le rapport de transport.'),
  ('TRANSPORT_MOVEMENT', 'TRANSPORT_EQUIPMENT', '0..n', 'Un mouvement de transport peut regrouper plusieurs équipements ; un équipement peut se rapporter à plusieurs mouvements.');
INSERT INTO rdm.party_role (code, category, label_en, label_fr, definition, bie_path, mapped_to, keywords, sort_order, actor_group, function_code) VALUES
  ('PAYER', 'SETTLEMENT', 'Payer', 'Payeur', 'The party responsible for making settlement relating to a payment.', 'tradeTransaction/applicableHeaderTradeSettlement/payer', 'Header_ Trade Settlement. Payer. Trade_ Party ; Payment_ Trade Settlement. Payer. Trade_ Party', '{"payeur","donneur d''ordre","payer"}', 200, 'CUSTOMER', 'PR'),
  ('PAYEE', 'SETTLEMENT', 'Payee', 'Bénéficiaire', 'The party which receives a payment.', 'tradeTransaction/applicableHeaderTradeSettlement/payee', 'Header_ Trade Settlement. Payee. Trade_ Party ; Payment_ Trade Settlement. Payee. Trade_ Party', '{"beneficiaire","bénéficiaire","payee","beneficiary"}', 210, 'SUPPLIER', 'PE'),
  ('PAYER_BANK', 'FINANCIAL', 'Payer''s financial institution', 'Banque du payeur', 'The financial institution holding the account of the payer (debtor).', 'tradeSettlementPayment/specifiedPaymentTradeSettlement/specifiedTradeSettlementPaymentMeans/payerSpecifiedDebtorFinancialInstitution', 'Trade Settlement_ Payment Means. Payer Specified. Debtor_ Financial Institution', '{"banque du payeur","banque domiciliataire","banque de l''importateur","payer bank"}', 220, 'INTERMEDIARY', 'PH'),
  ('PAYEE_BANK', 'FINANCIAL', 'Payee''s financial institution', 'Banque du bénéficiaire', 'The financial institution holding the account of the payee (creditor).', 'tradeSettlementPayment/specifiedPaymentTradeSettlement/specifiedTradeSettlementPaymentMeans/payeeSpecifiedCreditorFinancialInstitution', 'Trade Settlement_ Payment Means. Payee Specified. Creditor_ Financial Institution', '{"banque du beneficiaire","banque du bénéficiaire","banque de l''exportateur","payee bank"}', 230, 'INTERMEDIARY', 'BF'),
  ('INSURER', 'INSURANCE', 'Insurer', 'Assureur', 'The party providing the cargo insurance coverage for the consignment.', 'specifiedConsignment/applicableCargoInsurance/coverage', 'Transport_ Cargo Insurance. Coverage. Trade_ Party', '{"assureur","compagnie d''assurance","insurer"}', 240, 'INTERMEDIARY', 'IN'),
  ('SHIP_AGENT', 'TRANSPORT', 'Ship agent (carrier''s agent)', 'Consignataire de navire', 'The party acting on behalf of the carrier (ship owner or operator) at a port of call (UN/CEFACT Rec. 45).', 'specifiedConsignment/carrier', 'Supply Chain_ Consignment. Carrier. Trade_ Party (rôle CG : agent du transporteur)', '{"consignataire","consignataire de navire","agent maritime","ship agent"}', 250, 'INTERMEDIARY', 'CG'),
  ('CUSTOMS_TRANSIT_AGENT', 'CUSTOMS', 'Customs transit agent', 'Agent de transit douanier', 'The party acting as agent for the customs transit procedure of the consignment.', 'specifiedConsignment/customsTransitAgent', 'Supply Chain_ Consignment. Customs Transit Agent. Trade_ Party', '{"principal oblige","principal obligé","transit agent","agent de transit"}', 260, 'INTERMEDIARY', 'AF'),
  ('CONSOLIDATOR', 'TRANSPORT', 'Consolidator', 'Groupeur', 'The party consolidating cargo from several consignors (groupage).', 'specifiedConsignment/consolidator', 'Supply Chain_ Consignment. Consolidator. Trade_ Party', '{"groupeur","groupage","consolidator"}', 270, 'INTERMEDIARY', 'CS'),
  ('BROKER', 'TRADE', 'Broker / sales agent', 'Courtier', 'The party acting as intermediary in the sale, on behalf of the seller.', 'tradeTransaction/applicableHeaderTradeAgreement/salesAgent', 'Header_ Trade Agreement. Sales Agent. Trade_ Party', '{"courtier","agent commercial","broker","sales agent"}', 280, 'INTERMEDIARY', 'SR'),
  ('CHAMBER_OF_COMMERCE', 'AUTHORITY', 'Chamber of commerce', 'Chambre de commerce', 'The body issuing or certifying the certificate of origin of the goods.', 'tradeTransaction/includedTradeLineItem/specifiedTradeProduct/certificationEvidenceReferenceReferencedDocument/issuer', 'Trade_ Product. Certification Evidence Reference. Referenced_ Document. Issuer. Trade_ Party', '{"chambre de commerce","cci","chamber of commerce"}', 290, 'INTERMEDIARY', 'GB'),
  ('CUSTOMS_AUTHORITY', 'AUTHORITY', 'Customs', 'Douane', 'The customs administration receiving the declaration (recipient of the regulatory message).', 'exchangedDocument/recipient', 'Exchanged_ Document. Recipient. Trade_ Party (rôle CM)', '{"douane","douanes","bureau de douane","customs"}', 300, 'AUTHORITY', 'CM'),
  ('PLANT_PROTECTION_AUTHORITY', 'AUTHORITY', 'National plant protection organization', 'Organisation nationale de la protection des végétaux (ONPV)', 'The official service responsible for phytosanitary certification and import controls (IPPC, ISPM 7, 12, 20, 23).', 'exchangedDocument/recipient', 'Exchanged_ Document. Recipient. Trade_ Party (rôle VQ)', '{"onpv","phytosanitaire","protection des vegetaux","protection des végétaux","agriculture"}', 310, 'AUTHORITY', 'VQ'),
  ('HEALTH_AUTHORITY', 'AUTHORITY', 'Health authority', 'Autorité sanitaire', 'The public health or veterinary authority controlling goods at the border.', 'exchangedDocument/recipient', 'Exchanged_ Document. Recipient. Trade_ Party (rôle VQ)', '{"sante","santé","sanitaire","veterinaire","vétérinaire","health"}', 320, 'AUTHORITY', 'VQ'),
  ('ENVIRONMENT_AUTHORITY', 'AUTHORITY', 'Environment authority', 'Autorité environnementale', 'The authority applying environmental conventions (CITES, Basel, Rotterdam, Stockholm) to cross-border movements.', 'exchangedDocument/recipient', 'Exchanged_ Document. Recipient. Trade_ Party (rôle VQ)', '{"environnement","cites","environment"}', 330, 'AUTHORITY', 'VQ'),
  ('STANDARDS_AUTHORITY', 'AUTHORITY', 'Standards authority', 'Organisme de normalisation et de contrôle de conformité', 'The body checking the conformity of goods with technical regulations and standards.', 'exchangedDocument/recipient', 'Exchanged_ Document. Recipient. Trade_ Party (rôle VQ)', '{"normes","normalisation","conformite","conformité","standards"}', 340, 'AUTHORITY', 'VQ'),
