-- =============================================================================================
-- NEXORA · procedures — V6 : complétion du Supply Chain Reference Data Model UN/CEFACT D23B et couche Buy-Ship-Pay
-- Source normative : publication SCRDM (service.unece.org/trade/uncefact/publication/SupplyChainMGMT/SCRDM/HTML/001.htm),
--   forme machine github.com/uncefact/spec-JSONschema — library/BuyShipPay/D23B (UNECE-SCRDMContextCCL.json,
--   UNECE-SCRDMMaster.json, UNECE-BSPContextCCL.json, UNECE-BasicComponents.json, codelists/*.json).
-- Enrichissement : supports de formation e-GUCE 3G (BSP / ISCRM, Recommandations UN/CEFACT 1 à 48, MD de l'OMD,
--   EDIFACT, ebXML, NIMP, Convention FAL, ZLECAf, CMR), Douala, mai 2025.
--
--   1. 27 ABIE renvoyant à la bibliothèque BSP (vides en V2) : DEN, définition et 151 BIE
--   2. 127 cardinalités corrigées (maxItems = 1 → x..1 ; propriété requise → 1..x)
--   3. Types de données (86 UDT/QDT) et 129 listes de codes (valeurs : V7)
--   4. 188 restrictions contextuelles (propriétés exclues selon le chemin)
--   5. Couche BSP : domaines, processus, entités de haut niveau et leurs règles, rôles complétés,
--      messages d'échange (BSP-RDM D23B et UN/EDIFACT), instruments de référence et leurs liens
-- =============================================================================================

-- 1. ABIE : origine contextualisée (SCRDM) ou renvoi intégral à la bibliothèque BSP
ALTER TABLE rdm.abie ADD COLUMN source VARCHAR(5) NOT NULL DEFAULT 'SCRDM' CHECK (source IN ('SCRDM', 'BSP'));
COMMENT ON COLUMN rdm.abie.source IS 'SCRDM : restriction contextualisée de l''ABIE BSP ; BSP : ABIE de la bibliothèque BSP D23B repris sans restriction.';
UPDATE rdm.abie SET den = 'Applied_ Tax. Details', definition = 'A total levy or payment for the support of a government that is required of persons, groups, or businesses within the domain of that government.', source = 'BSP' WHERE release_id = (SELECT release_id FROM rdm.standard_release WHERE family='SCRDM' AND release_code='D23B') AND abie_code = 'appliedTax';
UPDATE rdm.abie SET den = 'Available_ Period. Details', definition = 'A specific period of time such as the length of time between two known date/time points, from a start date onwards, or up to an end date for which something is available.', source = 'BSP' WHERE release_id = (SELECT release_id FROM rdm.standard_release WHERE family='SCRDM' AND release_code='D23B') AND abie_code = 'availablePeriod';
UPDATE rdm.abie SET den = 'Document_ Version. Details', definition = 'A specific variant of a document.', source = 'BSP' WHERE release_id = (SELECT release_id FROM rdm.standard_release WHERE family='SCRDM' AND release_code='D23B') AND abie_code = 'documentVersion';
UPDATE rdm.abie SET den = 'Financial Institution_ Address. Details', definition = 'The location at which a financial institution may be found or reached.', source = 'BSP' WHERE release_id = (SELECT release_id FROM rdm.standard_release WHERE family='SCRDM' AND release_code='D23B') AND abie_code = 'financialInstitutionAddress';
UPDATE rdm.abie SET den = 'Goods_ Production. Details', definition = 'The making or manufacturing of goods, such as from components or raw materials.', source = 'BSP' WHERE release_id = (SELECT release_id FROM rdm.standard_release WHERE family='SCRDM' AND release_code='D23B') AND abie_code = 'goodsProduction';
UPDATE rdm.abie SET den = 'Instructed_ Temperature. Details', definition = 'Temperature settings instructed for storage or movement of goods.', source = 'BSP' WHERE release_id = (SELECT release_id FROM rdm.standard_release WHERE family='SCRDM' AND release_code='D23B') AND abie_code = 'instructedTemperature';
UPDATE rdm.abie SET den = 'Keyword. Details', definition = 'A significant word, part of word or phrase that is used to enable indexing of or searching within a textual repository, such as a product catalogue or library.', source = 'BSP' WHERE release_id = (SELECT release_id FROM rdm.standard_release WHERE family='SCRDM' AND release_code='D23B') AND abie_code = 'keyword';
UPDATE rdm.abie SET den = 'Material_ Goods Characteristic. Details', definition = 'A distinctive feature of a material contained within physical goods.', source = 'BSP' WHERE release_id = (SELECT release_id FROM rdm.standard_release WHERE family='SCRDM' AND release_code='D23B') AND abie_code = 'materialGoodsCharacteristic';
UPDATE rdm.abie SET den = 'Measurement. Details', definition = 'An amount, size, or extent as established by measuring.', source = 'BSP' WHERE release_id = (SELECT release_id FROM rdm.standard_release WHERE family='SCRDM' AND release_code='D23B') AND abie_code = 'measurement';
UPDATE rdm.abie SET den = 'Packaging_ Instructions. Details', definition = 'Packaging information of an instructive nature.', source = 'BSP' WHERE release_id = (SELECT release_id FROM rdm.standard_release WHERE family='SCRDM' AND release_code='D23B') AND abie_code = 'packagingInstructions';
UPDATE rdm.abie SET den = 'Payment_ Balance Out. Details', definition = 'Offset information to ensure that debits and credits are equal for a transaction.', source = 'BSP' WHERE release_id = (SELECT release_id FROM rdm.standard_release WHERE family='SCRDM' AND release_code='D23B') AND abie_code = 'paymentBalanceOut';
UPDATE rdm.abie SET den = 'Product Characteristic_ Condition. Details', definition = 'A state that applies to a product characteristic.', source = 'BSP' WHERE release_id = (SELECT release_id FROM rdm.standard_release WHERE family='SCRDM' AND release_code='D23B') AND abie_code = 'productCharacteristicCondition';
UPDATE rdm.abie SET den = 'Product_ Security Tag. Details', definition = 'A product tag device to provide protection from a peril such as theft.', source = 'BSP' WHERE release_id = (SELECT release_id FROM rdm.standard_release WHERE family='SCRDM' AND release_code='D23B') AND abie_code = 'productSecurityTag';
UPDATE rdm.abie SET den = 'Specified_ Range. Details', definition = 'A row, line or series, commonly used to express the difference between lowest and highest values.', source = 'BSP' WHERE release_id = (SELECT release_id FROM rdm.standard_release WHERE family='SCRDM' AND release_code='D23B') AND abie_code = 'range';
UPDATE rdm.abie SET den = 'Recorded_ Status. Details', definition = 'Recorded information relevant to a condition or a position of an object.', source = 'BSP' WHERE release_id = (SELECT release_id FROM rdm.standard_release WHERE family='SCRDM' AND release_code='D23B') AND abie_code = 'recordedStatus';
UPDATE rdm.abie SET den = 'Reference_ Price. Details', definition = 'A reference to a sum of money for which something is or may be bought or sold.', source = 'BSP' WHERE release_id = (SELECT release_id FROM rdm.standard_release WHERE family='SCRDM' AND release_code='D23B') AND abie_code = 'referencePrice';
UPDATE rdm.abie SET den = 'Supply Chain_ Reference. Details', definition = 'The identification of related information in a supply chain context.', source = 'BSP' WHERE release_id = (SELECT release_id FROM rdm.standard_release WHERE family='SCRDM' AND release_code='D23B') AND abie_code = 'reference';
UPDATE rdm.abie SET den = 'Referenced_ Product. Details', definition = 'A reference to a product or service produced by human or mechanical effort or by a natural process for trading purposes.', source = 'BSP' WHERE release_id = (SELECT release_id FROM rdm.standard_release WHERE family='SCRDM' AND release_code='D23B') AND abie_code = 'referencedProduct';
UPDATE rdm.abie SET den = 'Registered_ Tax. Details', definition = 'A registered tax or duty system pertaining to an authority.', source = 'BSP' WHERE release_id = (SELECT release_id FROM rdm.standard_release WHERE family='SCRDM' AND release_code='D23B') AND abie_code = 'registeredTax';
UPDATE rdm.abie SET den = 'Supply Chain_ Schedule. Details', definition = 'A series of planned activities or things to be done in this supply chain.', source = 'BSP' WHERE release_id = (SELECT release_id FROM rdm.standard_release WHERE family='SCRDM' AND release_code='D23B') AND abie_code = 'schedule';
UPDATE rdm.abie SET den = 'Section_ Segment. Details', definition = 'The parts into which a segment is or may be divided.', source = 'BSP' WHERE release_id = (SELECT release_id FROM rdm.standard_release WHERE family='SCRDM' AND release_code='D23B') AND abie_code = 'sectionSegment';
UPDATE rdm.abie SET den = 'Specification_ Query. Details', definition = 'A formally raised question or request for information about this specification.', source = 'BSP' WHERE release_id = (SELECT release_id FROM rdm.standard_release WHERE family='SCRDM' AND release_code='D23B') AND abie_code = 'specificationQuery';
UPDATE rdm.abie SET den = 'Specification_ Response. Details', definition = 'A response to a specification query.', source = 'BSP' WHERE release_id = (SELECT release_id FROM rdm.standard_release WHERE family='SCRDM' AND release_code='D23B') AND abie_code = 'specificationResponse';
UPDATE rdm.abie SET den = 'Temperature Setting_ Instructions. Details', definition = 'Temperature setting related information of an instructive nature.', source = 'BSP' WHERE release_id = (SELECT release_id FROM rdm.standard_release WHERE family='SCRDM' AND release_code='D23B') AND abie_code = 'temperatureSettingInstructions';
UPDATE rdm.abie SET den = 'Trade Product_ Feature. Details', definition = 'Distinctive or characteristic parts of a trade product.', source = 'BSP' WHERE release_id = (SELECT release_id FROM rdm.standard_release WHERE family='SCRDM' AND release_code='D23B') AND abie_code = 'tradeProductFeature';
UPDATE rdm.abie SET den = 'Trade Settlement Line_ Monetary Summation. Details', definition = 'A collection of monetary amount totals, specified at line level, for a trade settlement.', source = 'BSP' WHERE release_id = (SELECT release_id FROM rdm.standard_release WHERE family='SCRDM' AND release_code='D23B') AND abie_code = 'tradeSettlementLineMonetarySummation';
UPDATE rdm.abie SET den = 'Trade_ Workflow Object. Details', definition = 'An object used in the management of the status changes in a business process.', source = 'BSP' WHERE release_id = (SELECT release_id FROM rdm.standard_release WHERE family='SCRDM' AND release_code='D23B') AND abie_code = 'tradeWorkflowObject';


